package com.angle.trading.security;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.authentication.AuthenticationFailureHandler;import org.springframework.stereotype.Component;import jakarta.servlet.http.*;import java.io.IOException;@Componentpublic class CustomAuthenticationFailureHandler        implements AuthenticationFailureHandler {    private static final Logger log =            LoggerFactory.getLogger(CustomAuthenticationFailureHandler.class);    @Override    public void onAuthenticationFailure(HttpServletRequest request,                                        HttpServletResponse response,                                        AuthenticationException exception)            throws IOException {        log.info("Login Failed");        response.sendRedirect("/auth/login?error");    }}